    getPaintProperty<K extends keyof AllPaintProperties>(name: K): AllPaintProperties[K] {
        if (name.endsWith(TRANSITION_SUFFIX)) {
            const baseName = name.slice(0, -TRANSITION_SUFFIX.length);
